function HabitIcon({ icon, size = 18 }: { icon: string; size?: number }) {
  const Icon = icon === 'moon' ? Moon : icon === 'sun' ? Sun : icon === 'footprints' ? Footprints : BookOpen
  return <Icon size={size} />
}

function previousScheduledDate(date: string, targetDays: number[]) {
  for (let offset = 1; offset <= 7; offset += 1) {
    const candidate = shiftDate(date, -offset)
    if (targetDays.includes(fromDateKey(candidate).getDay())) return candidate
  }
  return undefined
}

function habitStats(habit: Habit) {
  const today = todayKey()
  const completed = new Set(habit.completedDates)
  const currentStart = completed.has(today) ? today : previousScheduledDate(today, habit.targetDays)
  let current = currentStart && completed.has(currentStart) ? 1 : 0
  let cursor = currentStart
  while (current && cursor) {
    const previous = previousScheduledDate(cursor, habit.targetDays)
    if (!previous || !completed.has(previous)) break
    current += 1
    cursor = previous
  }
  const sorted = [...completed].filter((date) => habit.targetDays.includes(fromDateKey(date).getDay())).sort()
  let best = 0
  let run = 0
  let previous = ''
  sorted.forEach((date) => {
    if (previous && previousScheduledDate(date, habit.targetDays) === previous) run += 1
    else run = 1
    previous = date
    best = Math.max(best, run)
  })
  const week = getLastDays(7).filter((date) => habit.targetDays.includes(fromDateKey(date).getDay()))
  const weekDone = week.filter((date) => completed.has(date)).length
  return { current, best, weekDone, weekTotal: week.length, percentage: percent(weekDone, week.length) }
}

function HabitForm({ habit, onClose, onSave }: { habit: Habit; onClose: () => void; onSave: (habit: Habit) => void }) {
  const [draft, setDraft] = useState(habit)
  const [error, setError] = useState('')
  useEffect(() => { setDraft(habit); setError('') }, [habit])
  const toggleDay = (day: number) => setDraft({ ...draft, targetDays: draft.targetDays.includes(day) ? draft.targetDays.filter((item) => item !== day) : [...draft.targetDays, day].sort() })
  const save = () => { if (!draft.name.trim()) { setError('Name the habit so it can become visible.'); return } if (!draft.targetDays.length) { setError('Choose at least one day.'); return } onSave({ ...draft, name: draft.name.trim() }) }
  return <Modal open onClose={onClose} title={habit.name ? 'Edit habit' : 'New habit'} eyebrow="A small repeatable action"><div className="space-y-5"><TextField autoFocus label="Habit name" placeholder="e.g. Stretch for 10 minutes" value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} error={error} /><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.1em] text-muted">Frequency</p><div className="grid grid-cols-3 gap-2">{(['daily', 'weekly', 'custom'] as HabitFrequency[]).map((frequency) => <button type="button" key={frequency} aria-pressed={draft.frequency === frequency} onClick={() => setDraft({ ...draft, frequency })} className={`rounded-[12px] border px-3 py-2.5 text-sm font-semibold capitalize ${draft.frequency === frequency ? 'border-moss bg-moss text-paper' : 'border-ink/10 text-muted hover:border-ink/25'}`}>{frequency}</button>)}</div></div><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.1em] text-muted">Target days</p><div className="flex gap-2">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((label, day) => <button type="button" key={`${label}-${day}`} aria-pressed={draft.targetDays.includes(day)} onClick={() => toggleDay(day)} className={`flex h-9 w-9 items-center justify-center rounded-full text-xs font-bold ${draft.targetDays.includes(day) ? 'bg-citrus text-ink' : 'bg-ink/5 text-muted hover:bg-ink/10'}`}>{label}</button>)}</div></div><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.1em] text-muted">Icon</p><div className="flex gap-2">{habitIconOptions.map((icon) => <button type="button" key={icon} aria-label={`Use ${icon} icon`} aria-pressed={draft.icon === icon} onClick={() => setDraft({ ...draft, icon })} className={`flex h-10 w-10 items-center justify-center rounded-[12px] ${draft.icon === icon ? 'bg-moss text-paper' : 'bg-ink/5 text-muted'}`}><HabitIcon icon={icon} size={17} /></button>)}</div></div><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.1em] text-muted">Color</p><div className="flex gap-2">{colorOptions.map((color) => <button type="button" key={color} aria-label={`Choose ${color} habit color`} aria-pressed={draft.color === color} onClick={() => setDraft({ ...draft, color })} className={`h-8 w-8 rounded-full border-2 ${draft.color === color ? 'border-ink' : 'border-transparent'}`} style={{ backgroundColor: color }} />)}</div></div><div className="flex justify-end gap-2 border-t border-ink/8 pt-5"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button onClick={save}>Save habit</Button></div></div></Modal>
}

function HabitDetail({ habit, onClose, onToggle, onEdit }: { habit: Habit; onClose: () => void; onToggle: () => void; onEdit: () => void }) {
  const stats = habitStats(habit)
  const days = getLastDays(28)
  return <Modal open onClose={onClose} title={habit.name} eyebrow="Habit detail" size="md"><div className="flex items-center gap-4 rounded-[18px] bg-paper/70 p-4"><span className="flex h-12 w-12 items-center justify-center rounded-[18px] text-ink" style={{ backgroundColor: `${habit.color}35` }}><HabitIcon icon={habit.icon} size={22} /></span><div className="flex-1"><p className="text-sm font-semibold text-ink">{stats.current} day current streak</p><p className="mt-1 text-xs text-muted">{stats.weekDone} of {stats.weekTotal || 0} planned check-ins this week</p></div><Button variant={habit.completedDates.includes(todayKey()) ? 'secondary' : 'primary'} onClick={onToggle}>{habit.completedDates.includes(todayKey()) ? 'Checked in' : 'Check in'}<Check size={15} /></Button></div><div className="mt-6 grid grid-cols-3 gap-3"><StatCard label="Current" value={`${stats.current}`} detail="day streak" icon={<Flame size={16} />} accent="bg-peach/45" /><StatCard label="Best" value={`${stats.best}`} detail="day streak" icon={<Trophy size={16} />} accent="bg-citrus/60" /><StatCard label="This week" value={`${stats.percentage}%`} detail="completion" icon={<BarChart3 size={16} />} accent="bg-lavender/35" /></div><div className="mt-6"><div className="mb-3 flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[0.1em] text-muted">Last 4 weeks</p><span className="text-xs text-muted">{formatDate(days[0])} — {formatDate(days[days.length - 1])}</span></div><div className="grid grid-cols-7 gap-2">{days.map((date) => { const done = habit.completedDates.includes(date); const planned = habit.targetDays.includes(fromDateKey(date).getDay()); return <div key={date} className="flex flex-col items-center gap-1.5"><span className={`flex h-7 w-7 items-center justify-center rounded-lg ${done ? 'text-ink' : planned ? 'bg-ink/5 text-transparent' : 'bg-transparent text-transparent'}`} style={done ? { backgroundColor: habit.color } : undefined}>{done && <Check size={13} />}</span><span className="text-[9px] text-muted">{fromDateKey(date).getDate()}</span></div> })}</div></div><div className="mt-6 flex justify-end border-t border-ink/8 pt-5"><Button variant="secondary" onClick={onEdit}><Pencil size={15} />Edit habit</Button></div></Modal>
}

export function HabitsView({ habits, onToggleHabit, onSaveHabit, onDeleteHabit }: Pick<FlowActions, 'onToggleHabit' | 'onSaveHabit' | 'onDeleteHabit'> & { habits: Habit[] }) {
  const [editor, setEditor] = useState<Habit | null>(null)
  const [detail, setDetail] = useState<Habit | null>(null)
  const today = todayKey()
  const newHabit = (): Habit => ({ id: uid('habit'), name: '', frequency: 'daily', targetDays: [0, 1, 2, 3, 4, 5, 6], icon: 'sun', color: colorOptions[0], completedDates: [], createdAt: new Date().toISOString() })
  return <PageFrame><div className="signal-line flex flex-col gap-5 pb-1 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-1 text-xs text-muted">A practice is a promise you can keep small.</p><h2 className="font-display text-3xl text-ink sm:text-4xl">Your habit rhythm.</h2></div><Button onClick={() => setEditor(newHabit())}><Plus size={17} />New habit</Button></div><div className="grid gap-4 sm:grid-cols-3"><StatCard label="In motion" value={`${habits.length}`} detail="active habits" icon={<Flame size={18} />} /><StatCard label="Checked in" value={`${habits.filter((habit) => habit.completedDates.includes(today)).length}/${habits.length}`} detail="for today" icon={<Check size={18} />} accent="bg-fern/25" /><StatCard label="Best rhythm" value={`${Math.max(...habits.map((habit) => habitStats(habit).best), 0)}`} detail="day streak" icon={<Trophy size={18} />} accent="bg-peach/45" /></div><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Today" title="Check in, without the drama" description="Consistency grows when the action stays visible and kind." /><div className="grid gap-3 md:grid-cols-2">{habits.map((habit) => { const stats = habitStats(habit); const complete = habit.completedDates.includes(today); return <div key={habit.id} className="group rounded-[18px] border border-ink/8 bg-paper/60 p-4 transition hover:border-ink/15"><div className="flex items-start gap-3"><button onClick={() => onToggleHabit(habit)} aria-label={`${complete ? 'Undo' : 'Complete'} ${habit.name}`} className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-[18px] transition ${complete ? 'text-ink' : 'text-muted'}`} style={{ backgroundColor: complete ? habit.color : `${habit.color}22` }}><HabitIcon icon={habit.icon} size={20} /></button><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><button onClick={() => setDetail(habit)} className="text-left"><h3 className={`font-semibold text-ink ${complete ? 'line-through opacity-60' : ''}`}>{habit.name}</h3><p className="mt-1 text-xs text-muted">{stats.current} day streak · {stats.percentage}% this week</p></button><div className="flex sm:opacity-0 sm:transition sm:group-hover:opacity-100"><IconButton label={`Edit ${habit.name}`} onClick={() => setEditor(habit)} className="h-8 w-8"><Edit3 size={14} /></IconButton><IconButton label={`Delete ${habit.name}`} onClick={() => onDeleteHabit(habit.id)} className="h-8 w-8"><Trash2 size={14} /></IconButton></div></div><div className="mt-4 flex gap-1.5">{getLastDays(7).map((date) => <span key={date} className={`h-2 flex-1 rounded-full ${habit.completedDates.includes(date) ? '' : 'bg-ink/8'}`} style={habit.completedDates.includes(date) ? { backgroundColor: habit.color } : undefined} />)}</div></div></div></div> })}</div></Card><div className="grid gap-6 lg:grid-cols-[1.05fr_0.95fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Weekly view" title="The shape of your week" /><div className="overflow-x-auto"><div className="min-w-[580px]"><div className="grid grid-cols-[minmax(150px,1fr)_repeat(7,38px)] items-center gap-2 border-b border-ink/8 pb-3 text-center text-[10px] font-bold uppercase tracking-widest text-muted"><span className="text-left">Habit</span>{getLastDays(7).map((date) => <span key={date}>{fromDateKey(date).toLocaleDateString('en-US', { weekday: 'short' }).slice(0, 1)}</span>)}</div>{habits.map((habit) => <div key={habit.id} className="grid grid-cols-[minmax(150px,1fr)_repeat(7,38px)] items-center gap-2 border-b border-ink/7 py-3 last:border-0"><span className="truncate text-xs font-semibold text-ink">{habit.name}</span>{getLastDays(7).map((date) => { const done = habit.completedDates.includes(date); const planned = habit.targetDays.includes(fromDateKey(date).getDay()); return <span key={date} className={`mx-auto flex h-7 w-7 items-center justify-center rounded-lg text-[10px] ${done ? 'text-ink' : planned ? 'bg-ink/5 text-transparent' : 'text-transparent'}`} style={done ? { backgroundColor: habit.color } : undefined}>{done && <Check size={12} />}</span> })}</div>)}</div></div></Card><Card className="relative overflow-hidden bg-moss p-6 text-paper"><div className="absolute -right-12 -top-12 h-36 w-36 rounded-full bg-citrus/20 blur-3xl" /><div className="relative"><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-citrus">A helpful thought</p><h3 className="mt-4 max-w-sm font-display text-3xl leading-tight">Make the habit smaller than your resistance.</h3><p className="mt-4 max-w-sm text-sm leading-6 text-paper/65">A two-minute version still counts. EiFlow is here to help you notice the return, not punish the miss.</p></div></Card></div>{editor && <HabitForm habit={editor} onClose={() => setEditor(null)} onSave={(habit) => { onSaveHabit(habit); setEditor(null) }} />}{detail && <HabitDetail habit={detail} onClose={() => setDetail(null)} onToggle={() => { onToggleHabit(detail); setDetail({ ...detail, completedDates: detail.completedDates.includes(today) ? detail.completedDates.filter((date) => date !== today) : [...detail.completedDates, today] }) }} onEdit={() => { setEditor(detail); setDetail(null) }} />}</PageFrame>
}

function goalProgress(goal: Goal) { return percent(goal.milestones.filter((milestone) => milestone.completed).length, goal.milestones.length) }

function GoalForm({ goal, onClose, onSave }: { goal: Goal; onClose: () => void; onSave: (goal: Goal) => void }) {
  const [draft, setDraft] = useState(goal)
  const [error, setError] = useState('')
  const [milestoneTitle, setMilestoneTitle] = useState('')
  useEffect(() => { setDraft(goal); setError(''); setMilestoneTitle('') }, [goal])
  const addMilestone = () => { if (!milestoneTitle.trim()) return; const milestone: Milestone = { id: uid('milestone'), title: milestoneTitle.trim(), completed: false }; setDraft((current) => ({ ...current, milestones: [...current.milestones, milestone] })); setMilestoneTitle('') }
  const save = () => { if (!draft.title.trim()) { setError('Give the goal a name.'); return } if (!draft.targetDate) { setError('Choose a target date.'); return } onSave({ ...draft, title: draft.title.trim() }) }
  return <Modal open onClose={onClose} title={goal.title ? 'Edit goal' : 'New goal'} eyebrow="A direction with room to grow" size="md"><div className="space-y-4"><TextField autoFocus label="Goal title" placeholder="e.g. Ship the portfolio" value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} error={error} /><TextAreaField label="Description" placeholder="Why does this matter right now?" value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} /><div className="grid gap-4 sm:grid-cols-2"><TextField label="Category" placeholder="Work, health, learning..." value={draft.category} onChange={(event) => setDraft({ ...draft, category: event.target.value })} /><TextField label="Target date" type="date" value={draft.targetDate} onChange={(event) => setDraft({ ...draft, targetDate: event.target.value })} /></div><SelectField label="Status" value={draft.status} onChange={(event) => setDraft({ ...draft, status: event.target.value as Goal['status'] })}><option value="active">Active</option><option value="paused">Paused</option><option value="completed">Completed</option></SelectField><div><div className="mb-2 flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[0.1em] text-muted">Milestones</p><span className="text-[11px] text-muted">{draft.milestones.length} added</span></div><div className="flex gap-2"><input value={milestoneTitle} onChange={(event) => setMilestoneTitle(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); addMilestone() } }} placeholder="Add a visible next step" className="h-10 min-w-0 flex-1 rounded-[12px] border border-ink/10 bg-paper/80 px-3 text-sm text-ink outline-none focus:border-moss focus:ring-2 focus:ring-moss/10" /><Button type="button" variant="secondary" onClick={addMilestone}><Plus size={15} />Add</Button></div>{draft.milestones.length > 0 && <div className="mt-2 space-y-2">{draft.milestones.map((milestone) => <div key={milestone.id} className="flex items-center gap-2 rounded-[12px] bg-paper/60 px-3 py-2"><span className={`h-2 w-2 rounded-full ${milestone.completed ? 'bg-fern' : 'bg-citrus'}`} /><span className={`flex-1 text-xs font-semibold ${milestone.completed ? 'text-muted line-through' : 'text-ink'}`}>{milestone.title}</span><IconButton label={`Remove ${milestone.title}`} onClick={() => setDraft((current) => ({ ...current, milestones: current.milestones.filter((item) => item.id !== milestone.id) }))} className="h-7 w-7"><X size={13} /></IconButton></div>)}</div>}</div><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.1em] text-muted">Color</p><div className="flex gap-2">{colorOptions.map((color) => <button type="button" key={color} aria-label={`Choose ${color} goal color`} aria-pressed={draft.color === color} onClick={() => setDraft({ ...draft, color })} className={`h-8 w-8 rounded-full border-2 ${draft.color === color ? 'border-ink' : 'border-transparent'}`} style={{ backgroundColor: color }} />)}</div></div><div className="flex justify-end gap-2 border-t border-ink/8 pt-5"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button onClick={save}>Save goal</Button></div></div></Modal>
}

export function GoalsView({ goals, onSaveGoal, onDeleteGoal, onToggleMilestone }: Pick<FlowActions, 'onSaveGoal' | 'onDeleteGoal' | 'onToggleMilestone'> & { goals: Goal[] }) {
  const [filter, setFilter] = useState<'active' | 'completed' | 'paused'>('active')
  const [selectedId, setSelectedId] = useState(goals.find((goal) => goal.status === 'active')?.id ?? goals[0]?.id)
  const [editor, setEditor] = useState<Goal | null>(null)
  const shown = goals.filter((goal) => goal.status === filter)
  const selected = shown.find((goal) => goal.id === selectedId) ?? shown[0]
  useEffect(() => {
    if (!shown.some((goal) => goal.id === selectedId)) setSelectedId(shown[0]?.id)
  }, [selectedId, shown])
  const newGoal = (): Goal => ({ id: uid('goal'), title: '', description: '', category: 'Personal', targetDate: shiftDate(todayKey(), 30), status: 'active', color: colorOptions[0], milestones: [], createdAt: new Date().toISOString() })
  return <PageFrame><div className="signal-line flex flex-col gap-5 pb-1 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-1 text-xs text-muted">Long-term work needs a little tenderness, too.</p><h2 className="font-display text-3xl text-ink sm:text-4xl">A direction, not a deadline.</h2></div><Button onClick={() => setEditor(newGoal())}><Plus size={17} />New goal</Button></div><div className="flex gap-1 rounded-[12px] bg-ink/5 p-1 sm:w-fit">{(['active', 'completed', 'paused'] as const).map((item) => <button type="button" key={item} aria-pressed={filter === item} onClick={() => setFilter(item)} className={`rounded-lg px-4 py-2 text-xs font-bold capitalize transition ${filter === item ? 'bg-white text-ink shadow-sm' : 'text-muted'}`}>{item} <span className="ml-1 opacity-60">{goals.filter((goal) => goal.status === item).length}</span></button>)}</div><div className="grid gap-6 xl:grid-cols-[0.8fr_1.2fr]">{shown.length ? <Card className="p-3"><div className="space-y-2">{shown.map((goal) => { const progress = goalProgress(goal); return <button key={goal.id} onClick={() => setSelectedId(goal.id)} className={`w-full rounded-[18px] border p-4 text-left transition ${selected?.id === goal.id ? 'border-moss bg-moss/5' : 'border-transparent hover:border-ink/10 hover:bg-paper/70'}`}><div className="flex items-start gap-3"><span className="mt-1 h-3 w-3 shrink-0 rounded-full" style={{ backgroundColor: goal.color }} /><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><h3 className="truncate text-sm font-bold text-ink">{goal.title}</h3><span className="text-sm font-bold text-moss">{progress}%</span></div><p className="mt-1 line-clamp-1 text-xs text-muted">{goal.description}</p><div className="mt-3"><ProgressBar value={progress} color="bg-moss" /></div><p className="mt-2 text-[11px] text-muted">{goal.milestones.filter((milestone) => milestone.completed).length} of {goal.milestones.length} milestones · due {formatDate(goal.targetDate)}</p></div></div></button> })}</div></Card> : <EmptyState icon={<Target size={20} />} title={`No ${filter} goals`} description="Create a goal or move one into this view." action={<Button onClick={() => setEditor(newGoal())}><Plus size={16} />Create goal</Button>} />}{selected ? <Card className="relative overflow-hidden p-6 sm:p-8"><div className="absolute -right-20 -top-20 h-60 w-60 rounded-full blur-3xl" style={{ backgroundColor: `${selected.color}35` }} /><div className="relative"><div className="flex items-start justify-between gap-4"><div><Badge tone={selected.status === 'active' ? 'success' : selected.status === 'paused' ? 'warning' : 'lavender'}>{selected.status}</Badge><p className="mt-3 text-xs font-bold uppercase tracking-[0.1em] text-muted">{selected.category} · Target {formatDate(selected.targetDate, { month: 'long', day: 'numeric', year: 'numeric' })}</p><h3 className="mt-2 max-w-xl font-display text-4xl leading-tight text-ink sm:text-5xl">{selected.title}</h3></div><div className="flex"><IconButton label="Edit goal" onClick={() => setEditor(selected)}><Pencil size={16} /></IconButton><IconButton label="Delete goal" onClick={() => onDeleteGoal(selected.id)}><Trash2 size={16} /></IconButton></div></div><p className="mt-5 max-w-2xl text-sm leading-7 text-muted">{selected.description || 'Add a description to remember why this goal matters.'}</p><div className="my-8 flex items-center gap-5"><div className="relative h-28 w-28 shrink-0"><svg className="progress-ring h-full w-full" viewBox="0 0 112 112" fill="none"><circle cx="56" cy="56" r="46" stroke="rgba(31,39,35,0.1)" strokeWidth="9" /><circle cx="56" cy="56" r="46" stroke={selected.color} strokeLinecap="round" strokeWidth="9" strokeDasharray={2 * Math.PI * 46} strokeDashoffset={(2 * Math.PI * 46) - ((2 * Math.PI * 46 * goalProgress(selected)) / 100)} /></svg><span className="absolute inset-0 flex items-center justify-center font-display text-2xl text-ink">{goalProgress(selected)}%</span></div><div><p className="font-display text-2xl text-ink">{selected.milestones.filter((milestone) => milestone.completed).length} milestones complete</p><p className="mt-1 text-sm text-muted">Keep choosing the next visible step.</p></div></div><div className="border-t border-ink/8 pt-5"><div className="mb-3 flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[0.13em] text-muted">Milestones</p><span className="text-xs text-muted">{selected.milestones.length} total</span></div><div className="space-y-2">{selected.milestones.length ? selected.milestones.map((milestone) => <button key={milestone.id} onClick={() => onToggleMilestone(selected.id, milestone.id)} className="flex w-full items-center gap-3 rounded-[12px] bg-paper/65 p-3 text-left transition hover:bg-citrus/15"><span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 ${milestone.completed ? 'border-moss bg-moss text-white' : 'border-ink/15'}`}>{milestone.completed && <Check size={13} />}</span><span className={`flex-1 text-sm font-semibold ${milestone.completed ? 'text-muted line-through' : 'text-ink'}`}>{milestone.title}</span>{milestone.dueDate && <span className="text-xs text-muted">{formatDate(milestone.dueDate)}</span>}</button>) : <p className="rounded-[12px] bg-paper/60 p-4 text-sm text-muted">No milestones yet. Add them from Edit goal.</p>}</div></div></div></Card> : <EmptyState icon={<Target size={20} />} title="Choose a goal" description="Select a goal to see its progress." />}</div>{editor && <GoalForm goal={editor} onClose={() => setEditor(null)} onSave={(goal) => { onSaveGoal(goal); setSelectedId(goal.id); setEditor(null) }} />}</PageFrame>
}

function BlockForm({ block, onClose, onSave }: { block: PlannerBlock; onClose: () => void; onSave: (block: PlannerBlock) => void }) {
  const [draft, setDraft] = useState(block)
  const [error, setError] = useState('')
  useEffect(() => { setDraft(block); setError('') }, [block])
  const save = () => {
    if (!draft.title.trim()) { setError('Name the block so it earns its space.'); return }
    if (!isDateKey(draft.date) || !isTimeValue(draft.startTime) || !isTimeValue(draft.endTime)) { setError('Choose a valid date, start time, and end time.'); return }
    if (timeToMinutes(draft.endTime) <= timeToMinutes(draft.startTime)) { setError('End time needs to come after start time.'); return }
    onSave({ ...draft, title: draft.title.trim(), color: plannerColors[draft.category] })
  }
  return <Modal open onClose={onClose} title={block.title ? 'Edit time block' : 'New time block'} eyebrow="Shape the day"><div className="space-y-4"><TextField autoFocus label="Block name" placeholder="e.g. Deep work · writing" value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} error={error} /><div className="grid gap-4 sm:grid-cols-3"><TextField label="Date" type="date" value={draft.date} onChange={(event) => setDraft({ ...draft, date: event.target.value })} /><TextField label="Start" type="time" value={draft.startTime} onChange={(event) => setDraft({ ...draft, startTime: event.target.value })} /><TextField label="End" type="time" value={draft.endTime} onChange={(event) => setDraft({ ...draft, endTime: event.target.value })} /></div><SelectField label="Category" value={draft.category} onChange={(event) => setDraft({ ...draft, category: event.target.value as PlannerCategory })}>{plannerCategories.map((category) => <option key={category} value={category}>{plannerCategoryLabel[category]}</option>)}</SelectField><TextAreaField label="Notes" placeholder="What belongs inside this block?" value={draft.notes} onChange={(event) => setDraft({ ...draft, notes: event.target.value })} /><div className="flex justify-end gap-2 border-t border-ink/8 pt-5"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button onClick={save}>Save block</Button></div></div></Modal>
}

export function PlannerView({ state, onSaveBlock, onDeleteBlock, onMoveBlock }: { state: AppState; onSaveBlock: (block: PlannerBlock) => void; onDeleteBlock: (id: string) => void; onMoveBlock: (id: string, date: string) => void }) {
  const [anchor, setAnchor] = useState(new Date())
  const [selectedDay, setSelectedDay] = useState(todayKey())
  const [editor, setEditor] = useState<PlannerBlock | null>(null)
  const [dragging, setDragging] = useState<string | null>(null)
  const days = getWeekDays(anchor, state.settings.weekStartsOn)
  useEffect(() => {
    if (!days.includes(selectedDay)) setSelectedDay(days[0])
  }, [anchor, selectedDay, state.settings.weekStartsOn])
  const blocks = state.plannerBlocks
  const createBlock = (date = selectedDay): PlannerBlock => ({ id: uid('block'), title: '', date, startTime: '09:00', endTime: '10:00', category: 'deep-work', notes: '', color: plannerColors['deep-work'] })
  const changeWeek = (amount: number) => {
    const next = new Date(anchor)
    next.setDate(next.getDate() + amount * 7)
    const nextDays = getWeekDays(next, state.settings.weekStartsOn)
    const selectedIndex = days.indexOf(selectedDay)
    setAnchor(next)
    setSelectedDay(nextDays[selectedIndex >= 0 ? selectedIndex : 0])
  }
  const selectedTasks = state.tasks.filter((task) => task.dueDate === selectedDay)
  return <PageFrame><div className="signal-line flex flex-col gap-5 pb-1 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-1 text-xs text-muted">Scheduled blocks are containers; tasks are what you do inside them.</p><h2 className="font-display text-3xl text-ink sm:text-4xl">Give your time a shape.</h2></div><Button onClick={() => setEditor(createBlock())}><Plus size={17} />New time block</Button></div><Card className="p-4 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.13em] text-fern">Week of</p><p className="mt-1 font-display text-2xl text-ink">{formatDate(days[0], { month: 'long', day: 'numeric' })} — {formatDate(days[6], { month: 'long', day: 'numeric' })}</p></div><div className="flex gap-1"><IconButton label="Previous week" onClick={() => changeWeek(-1)}><ChevronLeft size={18} /></IconButton><IconButton label="Next week" onClick={() => changeWeek(1)}><ChevronRight size={18} /></IconButton></div></div><div className="mb-4 grid grid-cols-7 gap-1.5 sm:gap-2">{days.map((day) => { const selected = selectedDay === day; const isToday = day === todayKey(); return <button type="button" key={day} aria-pressed={selectedDay === day} onClick={() => setSelectedDay(day)} className={`rounded-[12px] p-2 text-center transition ${selected ? 'bg-moss text-paper' : 'bg-paper/75 text-muted hover:bg-ink/5'}`}><span className="block text-[10px] font-bold uppercase tracking-widest">{fromDateKey(day).toLocaleDateString('en-US', { weekday: 'short' }).slice(0, 3)}</span><span className={`mt-1 block font-display text-xl ${selected ? 'text-paper' : 'text-ink'}`}>{fromDateKey(day).getDate()}</span>{isToday && <span className={`mx-auto mt-1 block h-1 w-1 rounded-full ${selected ? 'bg-citrus' : 'bg-moss'}`} />}</button> })}</div><div className="grid gap-2 md:grid-cols-7">{days.map((day) => <div key={day} onDragOver={(event) => event.preventDefault()} onDrop={() => { if (dragging) onMoveBlock(dragging, day); setDragging(null) }} className={`min-h-44 rounded-[12px] border p-2 transition ${selectedDay === day ? 'border-moss/30 bg-moss/5' : 'border-ink/7 bg-paper/45'}`}><p className="mb-2 px-1 text-[10px] font-bold uppercase tracking-widest text-muted md:hidden">{fromDateKey(day).toLocaleDateString('en-US', { weekday: 'short' })}</p><div className="space-y-2">{blocks.filter((block) => block.date === day).sort((a, b) => a.startTime.localeCompare(b.startTime)).map((block) => <button draggable onDragStart={() => setDragging(block.id)} onDragEnd={() => setDragging(null)} key={block.id} onClick={() => setEditor(block)} className="w-full rounded-lg border-l-[3px] bg-white/80 p-2 text-left shadow-sm transition hover:-translate-y-0.5" style={{ borderLeftColor: block.color }}><p className="line-clamp-2 text-[11px] font-bold text-ink">{block.title}</p><p className="mt-1 text-[10px] text-muted">{formatTime(block.startTime)}</p></button>)}</div></div>)}</div><div className="mt-4 flex flex-wrap gap-3 border-t border-ink/8 pt-4 text-[11px] font-semibold text-muted">{plannerCategories.map((category) => <span key={category} className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full" style={{ backgroundColor: plannerColors[category] }} />{plannerCategoryLabel[category]}</span>)}</div></Card><div className="grid gap-6 lg:grid-cols-[1fr_0.75fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow={formatDate(selectedDay, { weekday: 'long', month: 'long', day: 'numeric' })} title="The day at a glance" /><div className="space-y-3">{blocks.filter((block) => block.date === selectedDay).length ? blocks.filter((block) => block.date === selectedDay).sort((a, b) => a.startTime.localeCompare(b.startTime)).map((block) => <div key={block.id} className="group flex items-center gap-3 rounded-[12px] bg-paper/60 p-3"><div className="w-16 text-xs font-semibold text-muted">{formatTime(block.startTime)}</div><div className="h-8 w-1 rounded-full" style={{ backgroundColor: block.color }} /><div className="min-w-0 flex-1"><p className="text-sm font-bold text-ink">{block.title}</p><p className="mt-0.5 text-xs text-muted">{formatTime(block.startTime)} – {formatTime(block.endTime)} · {plannerCategoryLabel[block.category]}</p></div><IconButton label={`Edit ${block.title}`} onClick={() => setEditor(block)} className="h-8 w-8"><Pencil size={14} /></IconButton><IconButton label={`Delete ${block.title}`} onClick={() => onDeleteBlock(block.id)} className="h-8 w-8"><Trash2 size={14} /></IconButton></div>) : <EmptyState icon={<CalendarDays size={20} />} title="A little room to shape" description="No blocks yet for this day." action={<Button onClick={() => setEditor(createBlock())}><Plus size={16} />Add block</Button>} />}</div></Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Tasks are different" title="Due on this day" description="A task is an outcome. A block is the space you give it." />{selectedTasks.length ? <div className="space-y-2">{selectedTasks.map((task) => <div key={task.id} className="flex items-center gap-3 rounded-[12px] border border-ink/7 p-3"><span className={`h-2 w-2 rounded-full ${categoryTone[task.category]}`} /><span className={`flex-1 text-sm font-semibold ${task.status === 'done' ? 'text-muted line-through' : 'text-ink'}`}>{task.title}</span><span className="text-xs text-muted">{task.dueTime ? formatTime(task.dueTime) : 'Anytime'}</span></div>)}</div> : <p className="rounded-[12px] bg-paper/60 p-5 text-sm text-muted">Nothing due here yet. That can be intentional.</p>}</Card></div>{editor && <BlockForm block={editor} onClose={() => setEditor(null)} onSave={(block) => { onSaveBlock(block); setEditor(null) }} />}</PageFrame>
}

export function FocusView({ state, onRecordFocus }: { state: AppState; onRecordFocus: (duration: number, taskId?: string, goalId?: string) => void }) {
  const [preset, setPreset] = useState(25)
  const [seconds, setSeconds] = useState(25 * 60)
  const [running, setRunning] = useState(false)
  const [complete, setComplete] = useState(false)
  const [endsAt, setEndsAt] = useState<number | null>(null)
  const [runId, setRunId] = useState(0)
  const completedRunRef = useRef<number | null>(null)
  const [taskId, setTaskId] = useState('')
  const [goalId, setGoalId] = useState('')
  const [soundHint, setSoundHint] = useState(false)
  useEffect(() => {
    if (taskId && !state.tasks.some((task) => task.id === taskId)) setTaskId('')
    if (goalId && !state.goals.some((goal) => goal.id === goalId)) setGoalId('')
  }, [goalId, state.goals, state.tasks, taskId])
  useEffect(() => {
    if (!running || endsAt === null) return
    const update = () => {
      const remaining = Math.max(0, Math.ceil((endsAt - Date.now()) / 1000))
      setSeconds(remaining)
      if (remaining === 0) {
        setRunning(false)
        setEndsAt(null)
        setComplete(true)
        if (completedRunRef.current !== runId) {
          completedRunRef.current = runId
          onRecordFocus(preset, taskId || undefined, goalId || undefined)
        }
      }
    }
    update()
    const timer = window.setInterval(update, 250)
    return () => window.clearInterval(timer)
  }, [endsAt, goalId, onRecordFocus, preset, runId, running, taskId])
  const setPresetTime = (minutes: number) => { setPreset(minutes); setSeconds(minutes * 60); setEndsAt(null); setRunning(false); setComplete(false) }
  const toggleRunning = () => {
    if (running) { setRunning(false); setEndsAt(null); return }
    setRunId((current) => current + 1)
    setEndsAt(Date.now() + Math.max(seconds, 1) * 1000)
    setRunning(true)
    setComplete(false)
  }
  const reset = () => { setSeconds(preset * 60); setEndsAt(null); setRunning(false); setComplete(false) }
  const minutes = Math.floor(seconds / 60).toString().padStart(2, '0')
  const secs = (seconds % 60).toString().padStart(2, '0')
  const progress = ((preset * 60 - seconds) / (preset * 60)) * 100
  const recent = state.focusSessions.slice().sort((a, b) => b.completedAt.localeCompare(a.completedAt)).slice(0, 5)
  return <PageFrame><div className="mx-auto max-w-5xl"><div className="signal-line mb-6 flex items-end justify-between pb-1"><div><p className="mb-1 text-xs text-muted">The world can wait for one small interval.</p><h2 className="font-display text-3xl text-ink sm:text-4xl">One thing, fully here.</h2></div><Badge tone="accent">Focus mode</Badge></div><div className="overflow-hidden rounded-[24px] bg-ink shadow-lift"><div className="relative flex min-h-[570px] flex-col items-center justify-center px-5 py-12 text-center sm:px-10"><div className="absolute inset-0 opacity-50" style={{ background: 'radial-gradient(circle at 50% 35%, rgba(215,243,107,0.17), transparent 35%)' }} /><div className="relative"><p className="text-[11px] font-bold uppercase tracking-[0.22em] text-citrus">{complete ? 'Session complete' : running ? 'In the zone' : 'Ready when you are'}</p>{complete ? <div className="mt-8 animate-fade-up"><div className="mx-auto flex h-24 w-24 items-center justify-center rounded-full bg-citrus text-ink"><Check size={40} strokeWidth={2.5} /></div><h3 className="mt-7 font-display text-4xl text-paper">That time counts.</h3><p className="mx-auto mt-3 max-w-sm text-sm leading-6 text-paper/60">You gave {preset} minutes to {taskId ? state.tasks.find((task) => task.id === taskId)?.title ?? 'a task' : goalId ? state.goals.find((goal) => goal.id === goalId)?.title ?? 'a goal' : 'your attention'}.</p><Button className="mt-7" onClick={reset}>Start another</Button></div> : <><div className="relative mx-auto mt-7 h-64 w-64 sm:h-72 sm:w-72"><svg className="progress-ring h-full w-full" viewBox="0 0 280 280" fill="none"><circle cx="140" cy="140" r="124" stroke="rgba(245,246,241,0.12)" strokeWidth="5" /><circle cx="140" cy="140" r="124" stroke="#d7f36b" strokeLinecap="round" strokeWidth="5" strokeDasharray={2 * Math.PI * 124} strokeDashoffset={(2 * Math.PI * 124) - ((2 * Math.PI * 124 * progress) / 100)} /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className="font-display text-6xl tracking-tight text-paper sm:text-7xl">{minutes}:{secs}</span><span className="mt-2 text-xs font-bold uppercase tracking-[0.15em] text-paper/45">{preset} minute session</span></div></div><div className="mt-8 flex justify-center gap-2">{[25, 45, 60].map((minutesOption) => <button type="button" key={minutesOption} aria-pressed={preset === minutesOption} onClick={() => setPresetTime(minutesOption)} className={`rounded-full px-4 py-2 text-xs font-bold transition ${preset === minutesOption ? 'bg-citrus text-ink' : 'bg-white/10 text-paper/60 hover:bg-white/15 hover:text-paper'}`}>{minutesOption} min</button>)}</div><div className="mt-6 flex items-center justify-center gap-2"><Button variant="secondary" className="min-w-32" onClick={toggleRunning}>{running ? <><Pause size={16} />Pause</> : <><Play size={16} />{seconds === preset * 60 ? 'Start' : 'Resume'}</>}</Button><IconButton label="Reset timer" onClick={reset} className="text-paper/60 hover:bg-white/10 hover:text-paper"><RotateCcw size={17} /></IconButton></div></>}</div></div><div className="grid gap-4 border-t border-white/10 bg-white/5 p-5 sm:grid-cols-2 sm:p-6"><div><p className="mb-2 text-[10px] font-bold uppercase tracking-[0.16em] text-paper/45">Link this session (optional)</p><div className="grid gap-2"><label htmlFor="focus-task" className="sr-only">Task to focus on</label><select id="focus-task" value={taskId} onChange={(event) => { setTaskId(event.target.value); if (event.target.value) setGoalId('') }} className="h-10 rounded-[12px] border border-white/10 bg-white/8 px-3 text-xs text-paper outline-none"><option value="" className="text-ink">No task linked</option>{state.tasks.filter((task) => task.status !== 'done').map((task) => <option className="text-ink" key={task.id} value={task.id}>{task.title}</option>)}</select><label htmlFor="focus-goal" className="sr-only">Goal to focus on</label><select id="focus-goal" value={goalId} onChange={(event) => { setGoalId(event.target.value); if (event.target.value) setTaskId('') }} className="h-10 rounded-[12px] border border-white/10 bg-white/8 px-3 text-xs text-paper outline-none"><option value="" className="text-ink">No goal linked</option>{state.goals.filter((goal) => goal.status === 'active').map((goal) => <option className="text-ink" key={goal.id} value={goal.id}>{goal.title}</option>)}</select></div></div><div className="flex flex-col justify-end sm:items-end"><button onClick={() => setSoundHint((value) => !value)} className="flex items-center gap-2 text-left text-xs font-semibold text-paper/55 hover:text-paper"><CircleHelp size={14} />{soundHint ? 'Sessions record automatically when the timer ends.' : 'How does this work?'}</button></div></div></div><div className="mt-6"><SectionHeading eyebrow="A little evidence" title="Recent focus sessions" description="Completed sessions are kept in your local workspace." />{recent.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{recent.map((session) => <Card key={session.id} className="p-4"><div className="flex items-center justify-between"><Zap size={16} className="text-fern" /><span className="font-display text-xl text-ink">{session.duration}m</span></div><p className="mt-4 truncate text-xs font-semibold text-ink">{session.taskId ? state.tasks.find((task) => task.id === session.taskId)?.title : session.goalId ? state.goals.find((goal) => goal.id === session.goalId)?.title : 'Unlinked session'}</p><p className="mt-1 text-[11px] text-muted">{formatDate(session.date)}</p></Card>)}</div> : <EmptyState icon={<TimerReset size={20} />} title="Your first session is waiting" description="Choose a preset and press start. There is no need to prepare." />}</div></div></PageFrame>
}

function dayMetric(sessions: FocusSession[], tasks: Task[], habits: Habit[], date: string) {
  const completedTasks = tasks.reduce((sum, task) => {
    const timestamps = task.completionHistory ?? (task.completedAt ? [task.completedAt] : [])
    return sum + timestamps.filter((timestamp) => dateKeyFromTimestamp(timestamp) === date).length
  }, 0)
  return { tasks: completedTasks, habits: habits.reduce((sum, habit) => sum + (habit.completedDates.includes(date) ? 1 : 0), 0), focus: sessions.filter((session) => session.date === date).reduce((sum, session) => sum + session.duration, 0) }
}

export function AnalyticsView({ state }: { state: AppState }) {
  const [range, setRange] = useState<7 | 30>(7)
  const days = getLastDays(range)
  const metrics = days.map((date) => ({ date, ...dayMetric(state.focusSessions, state.tasks, state.habits, date) }))
  const totalTasks = metrics.reduce((sum, metric) => sum + metric.tasks, 0)
  const totalHabitChecks = metrics.reduce((sum, metric) => sum + metric.habits, 0)
  const totalFocus = metrics.reduce((sum, metric) => sum + metric.focus, 0)
  const bestDay = metrics.reduce<(typeof metrics)[number] | undefined>((best, metric) => {
    const score = metric.tasks + metric.habits + metric.focus / 25
    const bestScore = best ? best.tasks + best.habits + best.focus / 25 : 0
    return score > bestScore ? metric : best
  }, undefined)
  const rangeDays = new Set(days)
  const hours = state.focusSessions.filter((session) => rangeDays.has(session.date)).reduce<Record<string, number>>((acc, session) => { const hour = new Date(session.completedAt).getHours(); const key = `${hour}:00`; acc[key] = (acc[key] ?? 0) + session.duration; return acc }, {})
  const bestHour = Object.entries(hours).sort((a, b) => b[1] - a[1])[0]?.[0] ?? '—'
  const goalAverage = state.goals.length ? Math.round(state.goals.reduce((sum, goal) => sum + goalProgress(goal), 0) / state.goals.length) : 0
  return <PageFrame><div className="signal-line flex flex-col gap-5 pb-1 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-1 text-xs text-muted">Patterns are more useful than perfect streaks.</p><h2 className="font-display text-3xl text-ink sm:text-4xl">Notice what helps you flow.</h2></div><div className="flex gap-1 rounded-[12px] bg-ink/5 p-1">{([7, 30] as const).map((item) => <button type="button" key={item} aria-pressed={range === item} onClick={() => setRange(item)} className={`rounded-lg px-4 py-2 text-xs font-bold transition ${range === item ? 'bg-white text-ink shadow-sm' : 'text-muted'}`}>{item} days</button>)}</div></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Tasks completed" value={`${totalTasks}`} detail={`in the last ${range} days`} icon={<Check size={18} />} /><StatCard label="Habit check-ins" value={`${totalHabitChecks}`} detail="small returns" icon={<Flame size={18} />} accent="bg-peach/45" /><StatCard label="Focus minutes" value={formatDuration(totalFocus)} detail="recorded locally" icon={<Zap size={18} />} accent="bg-lavender/35" /><StatCard label="Goal progress" value={`${goalAverage}%`} detail="average across goals" icon={<Target size={18} />} accent="bg-fern/25" /></div><div className="grid gap-6 xl:grid-cols-[1.35fr_0.65fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Daily pulse" title={`Your last ${range} days`} description="Each bar combines completed tasks, habit check-ins, and focused minutes." /><div className="flex h-64 items-end gap-1.5 overflow-x-auto border-b border-ink/8 pb-0 sm:gap-2">{metrics.map((metric) => { const total = metric.tasks * 12 + metric.habits * 5 + metric.focus / 3; const maxActivity = Math.max(...metrics.map((item) => item.tasks * 12 + item.habits * 5 + item.focus / 3), 0); const height = maxActivity ? Math.max(8, Math.min(100, (total / maxActivity) * 100)) : 0; return <div key={metric.date} className="group flex min-w-[18px] flex-1 flex-col items-center justify-end gap-2 sm:min-w-[24px]"><div className="relative w-full max-w-8 rounded-t-lg bg-citrus transition group-hover:bg-fern" style={{ height: `${height}%` }}><span className="absolute bottom-full left-1/2 mb-2 hidden -translate-x-1/2 whitespace-nowrap rounded-lg bg-ink px-2 py-1 text-[10px] font-bold text-paper group-hover:block">{metric.focus}m · {metric.tasks} tasks</span></div><span className="text-[9px] text-muted">{range === 7 ? fromDateKey(metric.date).toLocaleDateString('en-US', { weekday: 'short' }).slice(0, 2) : fromDateKey(metric.date).getDate()}</span></div> })}</div></Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="A useful signal" title="Your best window" /><div className="rounded-[18px] bg-moss p-5 text-paper"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-citrus">Most focused time</p><p className="mt-2 font-display text-4xl">{bestHour}</p><p className="mt-2 text-sm leading-6 text-paper/65">That’s where your completed focus sessions tend to cluster.</p></div><div className="mt-5 rounded-[18px] bg-paper/70 p-5"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-fern">Most productive day</p><p className="mt-2 font-display text-2xl text-ink">{bestDay ? fromDateKey(bestDay.date).toLocaleDateString('en-US', { weekday: 'long' }) : 'Not enough data yet'}</p><p className="mt-1 text-xs text-muted">{bestDay ? `${bestDay.tasks} tasks · ${bestDay.habits} habits · ${bestDay.focus} focus minutes` : 'Complete a task or focus session to start a pattern.'}</p></div></Card></div><div className="grid gap-6 lg:grid-cols-2"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="By habit" title="Consistency, at a glance" />{state.habits.map((habit) => { const stats = habitStats(habit); return <div key={habit.id} className="mb-4 last:mb-0"><div className="mb-2 flex items-center justify-between"><span className="text-sm font-semibold text-ink">{habit.name}</span><span className="text-xs font-bold text-moss">{stats.percentage}%</span></div><ProgressBar value={stats.percentage} color="bg-moss" /></div> })}</Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="By goal" title="Long-view momentum" />{state.goals.map((goal) => <div key={goal.id} className="mb-4 last:mb-0"><div className="mb-2 flex items-center justify-between"><span className="truncate pr-3 text-sm font-semibold text-ink">{goal.title}</span><span className="text-xs font-bold text-moss">{goalProgress(goal)}%</span></div><ProgressBar value={goalProgress(goal)} color="bg-fern" /></div>)}</Card></div></PageFrame>
}

export function SettingsView({ state, onUpdateProfile, onUpdateSettings, onReset, onRestartOnboarding, onImport }: Pick<FlowActions, 'onUpdateProfile' | 'onUpdateSettings' | 'onReset' | 'onRestartOnboarding' | 'onImport'> & { state: AppState }) {
  const fileInput = useRef<HTMLInputElement>(null)
  const [importError, setImportError] = useState('')
  const profile = state.profile
  const exportData = () => {
    const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `eiflow-backup-${todayKey()}.json`
    anchor.click()
    window.setTimeout(() => URL.revokeObjectURL(url), 0)
  }
  const importData = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    event.target.value = ''
    if (!file) return
    if (file.size > MAX_IMPORT_BYTES) {
      setImportError('That backup is larger than 5 MB. Nothing was changed.')
      return
    }
    const reader = new FileReader()
    reader.onerror = () => setImportError('The backup could not be read. Nothing was changed.')
    reader.onload = () => {
      try {
        const parsed: unknown = JSON.parse(String(reader.result))
        if (!isAppState(parsed) || !onImport(parsed)) throw new Error('invalid')
        setImportError('')
      } catch {
        setImportError('That file does not look like an EiFlow backup. Nothing was changed.')
      }
    }
    reader.readAsText(file)
  }
  const update = (changes: Partial<Profile>) => onUpdateProfile({ ...profile, ...changes })
  return <PageFrame><div className="signal-line pb-1"><h2 className="font-display text-3xl text-ink sm:text-4xl">Make EiFlow yours.</h2></div><div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><div className="space-y-6"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Your profile" title="The person behind the plans" description="These details stay on this device and help shape your experience." /><div className="grid gap-4 sm:grid-cols-2"><TextField label="Name" value={profile.name} onChange={(event) => update({ name: event.target.value })} /><TextField label="Primary goal" value={profile.primaryGoal} onChange={(event) => update({ primaryGoal: event.target.value })} /></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><TextField label="Workday starts" type="time" value={profile.workingHours.start} onChange={(event) => update({ workingHours: { ...profile.workingHours, start: event.target.value } })} /><TextField label="Workday ends" type="time" value={profile.workingHours.end} onChange={(event) => update({ workingHours: { ...profile.workingHours, end: event.target.value } })} /></div></Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Appearance" title="Choose the atmosphere" /><div className="grid gap-3 sm:grid-cols-3">{(['light', 'dark', 'system'] as const).map((theme) => <button type="button" key={theme} aria-pressed={state.settings.theme === theme} onClick={() => onUpdateSettings({ ...state.settings, theme })} className={`rounded-[18px] border p-4 text-left transition ${state.settings.theme === theme ? 'border-moss bg-moss/5 ring-2 ring-moss/10' : 'border-ink/10 hover:border-ink/20'}`}><div className={`mb-4 h-12 rounded-[12px] ${theme === 'dark' ? 'bg-ink' : theme === 'light' ? 'bg-paper ring-1 ring-inset ring-ink/10' : 'bg-gradient-to-br from-paper via-paper to-ink'}`} /><p className="text-sm font-bold capitalize text-ink">{theme}</p><p className="mt-1 text-xs text-muted">{theme === 'system' ? 'Follow your device' : `Use ${theme} mode`}</p></button>)}</div></Card></div><div className="space-y-6"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Workspace" title="Your data, your device" description="EiFlow has no account or server. Everything lives in this browser." /><div className="space-y-2"><Button variant="secondary" className="w-full justify-start" onClick={exportData}><Download size={16} />Export all data as JSON</Button><Button variant="secondary" className="w-full justify-start" onClick={() => fileInput.current?.click()}><Upload size={16} />Import a JSON backup</Button><input ref={fileInput} type="file" accept="application/json,.json" className="hidden" onChange={importData} />{importError && <p className="rounded-[12px] bg-terracotta/10 p-3 text-xs font-medium text-terracotta" role="alert">{importError}</p>}</div></Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Start fresh" title="Reset your space" description="Useful for trying the demo again or handing the device to someone new." /><div className="space-y-2"><Button variant="secondary" className="w-full justify-start" onClick={() => { if (window.confirm('Reset all EiFlow data to the seeded demo?')) onReset() }}><RotateCcw size={16} />Reset demo data</Button><Button variant="secondary" className="w-full justify-start" onClick={() => { if (window.confirm('Restart onboarding? Your current data will stay safe.')) onRestartOnboarding() }}><SparklesIcon />Restart onboarding</Button></div></Card><div className="rounded-[18px] border border-ink/8 bg-paper/50 p-5"><div className="flex items-start gap-3"><CircleHelp size={17} className="mt-0.5 text-fern" /><div><p className="text-sm font-bold text-ink">A note on privacy</p><p className="mt-1 text-xs leading-5 text-muted">Your tasks, habits, goals, and focus history never leave this browser unless you choose to export them.</p></div></div></div></div></div></PageFrame>
}

function SparklesIcon() { return <span className="text-base">✦</span> }
